def _guards() -> None:
    """Database floors remain authoritative across restart and changed callers."""
    op.execute("""
CREATE FUNCTION nexus_company_execution_guard() RETURNS trigger AS $$
    BEGIN
      IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Execution identity is durable'; END IF;
      IF ROW(NEW.company_id,NEW.task_id,NEW.trace_id,NEW.actor_id,NEW.workspace_id,
             NEW.parent_task_id,NEW.run_id,NEW.registration_json,NEW.registration_hash,
             NEW.workflow_name,NEW.workflow_version,NEW.model_profile,NEW.model_registry_version,
             NEW.model_requests_limit,NEW.tool_attempts_limit,NEW.rework_rounds_limit,NEW.plan_revisions_limit)
         IS DISTINCT FROM
         ROW(OLD.company_id,OLD.task_id,OLD.trace_id,OLD.actor_id,OLD.workspace_id,
             OLD.parent_task_id,OLD.run_id,OLD.registration_json,OLD.registration_hash,
             OLD.workflow_name,OLD.workflow_version,OLD.model_profile,OLD.model_registry_version,
             OLD.model_requests_limit,OLD.tool_attempts_limit,OLD.rework_rounds_limit,OLD.plan_revisions_limit)
         THEN RAISE EXCEPTION 'Execution registration is immutable'; END IF;
      IF NEW.fence < OLD.fence OR NEW.segment_number < OLD.segment_number
         OR NEW.model_requests_used < OLD.model_requests_used
         OR NEW.model_requests_delegated < OLD.model_requests_delegated
         OR NEW.tool_attempts_used < OLD.tool_attempts_used
         OR NEW.tool_attempts_delegated < OLD.tool_attempts_delegated
         OR NEW.rework_rounds_used < OLD.rework_rounds_used
         OR NEW.rework_rounds_delegated < OLD.rework_rounds_delegated
         OR NEW.plan_revisions_used < OLD.plan_revisions_used
         OR NEW.plan_revisions_delegated < OLD.plan_revisions_delegated
         THEN RAISE EXCEPTION 'Execution counters or fence cannot reset'; END IF;
      RETURN NEW;
    END; $$ LANGUAGE plpgsql;
    """)
